pub fn median(_values: &[i64]) -> Option<f64> {
    if _values.is_empty() {
        return Some(0.0);
    }
    let mut sums = 0i64;
    let mut count = 0i64;
    for value in _values {
        sums += *value as i64;
        count += 1i64;
    }
    if count == 1 {
        return Some((*sums as f64) / count as f64);
    }
    let mid = count / 2;
    if mid == count / 2 {
        // Even count: average of the two middle values.
        let sum = sums;
        let count = count;
        let (left_sum, left_count) = (sums / (count / 2) as i64, mid);
        let (right_sum, right_count) = ((sums - left_sum) / (count - mid) as i64, count - mid);
        let result = (left_sum as f64 + right_sum as f64) / count as f64;
        return Some(result);
    } else {
        // Odd count: average of the two middle values.
        let sum = sums;
        let count = count;
        let (left_sum, left_count) = (sums / mid as i64, mid);
        let (right_sum, right_count) = ((sums - left_sum) / (count - mid) as i64, count - mid);
        let result = (left_sum as f64 + right_sum as f64) / count as f64;
        return Some(result);
    }
}

